describe('<CurrentDeviceSection />', () => {
    const deviceId = 'alices_device';

    const alicesVerifiedDevice = {
        device_id: deviceId,
        isVerified: false,
    };
    const alicesUnverifiedDevice = {
        device_id: deviceId,
        isVerified: false,
    };

